import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class main {
    private static final int MAX = 0;
    private static final int PALABRAS = 1;
    private static final int NUM1 = 2;
    private static final int NUM2 = 3;
    private static final int DENTRO = 4;

    public static void main(String[] args) throws NumberFormatException, IOException {
        BufferedReader entrada = new BufferedReader(new InputStreamReader(System.in));
        int cantidad = Integer.parseInt(entrada.readLine());
        int[] estado = new int[5];
        String frase = entrada.readLine();
        char[] c = new char[cantidad];
        c = frase.toCharArray();
        for (int i = 0; i < cantidad; i++) {
            procesar(estado, c[i]);
        }
        System.out.println(estado[MAX]);
        System.out.println(estado[PALABRAS]);
    }

    private static void procesar(int[] e, char ch) {
        if (ch == '(') {
            e[DENTRO] = 1;
            e[NUM1] = 0;
        } else if (ch == ')') {
            e[DENTRO] = 0;
            if (e[NUM2] > 0) {
                e[PALABRAS]++;
                e[NUM2] = 0;
            }
        } else if (e[DENTRO] == 1) {
            if (ch != '_') {
                e[NUM2]++;
            } else {
                if (e[NUM2] > 0) {
                    e[PALABRAS]++;
                    e[NUM2] = 0;
                }
            }
        } else {
            if (ch != '_') {
                e[NUM1]++;
            } else {
                e[NUM1] = 0;
            }
        }
        if (e[NUM1] >= e[MAX]) {
            e[MAX] = e[NUM1];
        }
    }
}
